import numpy as np

class WavyValley:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Ensure x is within bounds [-5, 5] per dimension
        x = np.clip(x, -5.0, 5.0)
        # Wavy structure per dimension with multiple local minima
        return np.sum(0.5 * x**2 + 2 * np.sin(3 * x) + 0.5 * np.cos(5 * x))

import numpy as np

class ExponentialDecayValley:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Exponential decay term that creates steep valleys near origin
        decay = np.exp(-0.5 * np.abs(x))
        # Periodic oscillations that become less pronounced with distance
        periodic = np.sin(3 * np.pi * x) * np.exp(-0.1 * np.abs(x))
        # Quadratic term to ensure global minimum at origin
        quadratic = 0.5 * x**2
        # Combine terms with different weights
        return np.sum(quadratic + 5 * decay + 2 * periodic)

import numpy as np

class LogarithmicPersistentValley:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Logarithmic base function: creates a shallow basin with weak gradient at boundaries
        # Behaves like x^2 near origin, but grows as log(x^2) at periphery
        base = np.log(1.0 + x**2)

        # Constant amplitude oscillations: creates high-frequency noise that does not decay
        # This challenges optimizers where the base gradient is weak
        oscillation = 0.5 * (1.0 - np.cos(10.0 * x))

        # Global minimum is at origin (f=0), non-negative everywhere
        return np.sum(base + oscillation)
